-- Готовое наполнение: цитаты с источниками, фильмы и книги, короткие задания («Мышление барбермаксера»),
-- челлендж «Быстрая запись» с правилами и задачами. Всё правится в админке (Контент и Программа)
alter table movies add column if not exists kind text not null default 'film' check (kind in ('film', 'book'));
alter table movies add column if not exists author text;
alter table challenges add column if not exists rules text;

